import axios from "axios";
import React, { useState, useEffect } from "react";

const Slider = ({ setIndicator }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [slides, setSlides] = useState([]);

  useEffect(() => {
    setIndicator(true);
    const fetchSlides = async () => {
      try {
        const response = await axios.get("http://localhost:5000/images");
        const sliderImages = response.data?.[0]?.slider?.filter((ele) => ele.isActive === true) ?? [];
        setSlides(sliderImages);
      } catch (error) {
        console.error("Error fetching images section content:", error);
      } finally {
        setIndicator(false);
      }
    };
    fetchSlides();
  }, []);

  useEffect(() => {
    if (slides.length > 0) {
      const timer = setTimeout(() => {
        goToNext();
      }, 5000); // Auto-slide every 5 seconds
      return () => clearTimeout(timer);
    }
  }, [currentIndex, slides.length]);

  const goToPrevious = () => {
    if (slides.length > 0) {
      setCurrentIndex((prevIndex) => (prevIndex - 1 + slides.length) % slides.length);
    }
  };

  const goToNext = () => {
    if (slides.length > 0) {
      setCurrentIndex((prevIndex) => (prevIndex + 1) % slides.length);
    }
  };

  const goToSlide = (slideIndex) => {
    if (slides.length > 0) {
      setCurrentIndex(slideIndex);
    }
  };

  return (
    <div style={sliderStyles}>
      {slides.length > 0 ? (
        <>
          <div onClick={goToPrevious} style={leftArrowStyles}>
            ❰
          </div>
          <div onClick={goToNext} style={rightArrowStyles}>
            ❱
          </div>
          <div className="slider-container">
            {slides.map((slide, index) => (
              <img
                key={index}
                className={`slide ${index === currentIndex ? "active" : ""}`}
                src={slide.url}
                alt={`Slide ${index + 1}`}
              />
            ))}
          </div>
          <div style={dotsContainerStyles}>
            {slides.map((_, slideIndex) => (
              <div
                key={slideIndex}
                style={{
                  ...dotStyle,
                  color: slideIndex === currentIndex ? "black" : "gray",
                }}
                onClick={() => goToSlide(slideIndex)}
              >
                ●
              </div>
            ))}
          </div>
        </>
      ) : (
        <p style={{ textAlign: "center", color: "red" }}>No active slides available</p>
      )}
    </div>
  );
};

const sliderStyles = {
  position: "relative",
  height: "700px",
  width: "100%",
  overflow: "hidden",
};

const leftArrowStyles = {
  position: "absolute",
  top: "50%",
  transform: "translate(0, -50%)",
  left: "32px",
  fontSize: "45px",
  color: "black",
  zIndex: 1,
  cursor: "pointer",
};

const rightArrowStyles = {
  position: "absolute",
  top: "50%",
  transform: "translate(0, -50%)",
  right: "32px",
  fontSize: "45px",
  color: "black",
  zIndex: 1,
  cursor: "pointer",
};

const dotsContainerStyles = {
  position: "absolute",
  bottom: "20px",
  left: "50%",
  transform: "translateX(-50%)",
  display: "flex",
  justifyContent: "center",
  zIndex: 1,
};

const dotStyle = {
  margin: "0 5px",
  cursor: "pointer",
  fontSize: "20px",
};

export default Slider;
